const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'Europe/Kyiv', year: 'numeric', month: '2-digit', day: '2-digit' }).formatToParts(new Date());
const values = Object.fromEntries(parts.map((part) => [part.type, part.value]));
const today = `${values.year}-${values.month}-${values.day}`;
const previous = new Date(`${today}T00:00:00.000Z`);
previous.setUTCDate(previous.getUTCDate() - 1);
const reportDate = previous.toISOString().slice(0, 10);
return [{ json: { reportDate } }];

const stats = $input.first().json ?? {};
const pending = Number(stats.totals?.pending ?? 0);
if (pending > 0) throw new Error(`Daily report not sent: ${pending} email(s) are still pending classification.`);
return $input.all();

const s = $('Get daily GimmeJob statistics').first().json;
const reconciliation = $('Reconcile unresolved job emails').first().json ?? {};
const activity = $input.first().json ?? {};
const t = s.totals ?? {};
const r = s.routing ?? {};
const ai = s.ai ?? {};
const c = s.byClassification ?? {};
const important = Array.isArray(s.important) ? s.important : [];
const vacancyChanges = Array.isArray(activity.vacancyChanges) ? activity.vacancyChanges : [];
const classifications = Array.isArray(activity.classifications) ? activity.classifications : [];
const needsLinking = Number(activity.resolutionNeedsAttention ?? 0);

const esc = (value) => String(value ?? '').replace(/[&<>"]/g, (ch) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' })[ch] ?? ch);
const n = (value) => Number(value ?? 0).toLocaleString('en-US');
const pct = Number(r.aiAvoidanceRatePct ?? 100).toFixed(1);
const time = (value) => {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? String(value ?? '') : new Intl.DateTimeFormat('en-GB', { timeZone: 'Europe/Kyiv', day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' }).format(date);
};
const resolutionText = (item) => {
  const resolution = item.resolution ?? {};
  const status = String(resolution.status ?? 'PENDING');
  if (status === 'MATCHED') {
    const vacancy = [resolution.matchedTitle, resolution.matchedCompany].filter(Boolean).join(' · ') || resolution.jobId || 'matched vacancy';
    const confidence = resolution.confidence === null || resolution.confidence === undefined ? '' : ` · ${Math.round(Number(resolution.confidence) * 100)}%`;
    return `Matched: ${esc(vacancy)} · ${esc(resolution.method || 'unknown method')}${confidence} · ${esc(resolution.statusNote || 'no status change')}`;
  }
  if (status === 'AMBIGUOUS') return 'Needs linking: multiple plausible vacancies.';
  if (status === 'UNRESOLVED') return 'Needs linking: no safe vacancy match.';
  if (status === 'NOT_APPLICABLE') return 'Vacancy matching not applicable.';
  return `Resolution: ${esc(status)}`;
};

const classRows = [
  ['Application received', c.APPLICATION_RECEIVED],
  ['Recruiter outreach', c.RECRUITER_OUTREACH],
  ['Interviews', c.INTERVIEW],
  ['Test tasks', c.TEST_TASK],
  ['Offers', c.OFFER],
  ['Rejections', c.REJECTION],
].map(([label, value]) => `<tr><td>${label}</td><td style="text-align:right"><b>${n(value)}</b></td></tr>`).join('');

const importantHtml = important.length
  ? `<h3>Important events</h3><ul>${important.map((item) => {
      const title = [item.classification, item.company, item.jobTitle].filter(Boolean).join(' · ');
      return `<li><b>${esc(title || item.classification)}</b><br>${esc(item.summary || item.subject || '')}${item.action ? `<br><small>Action: ${esc(item.action)}</small>` : ''}</li>`;
    }).join('')}</ul>`
  : '<h3>Important events</h3><p>None.</p>';

const vacancyChangesHtml = vacancyChanges.length
  ? `<h3>Vacancy changes by automation (${n(vacancyChanges.length)})</h3><ul>${vacancyChanges.map((item) => {
      const title = [item.title, item.company].filter(Boolean).join(' · ') || item.jobId;
      const field = item.field ? `<br><small>${esc(item.field)}: ${esc(item.beforeValue ?? '—')} → ${esc(item.afterValue ?? '—')}</small>` : '';
      return `<li><b>${esc(title)}</b><br>${esc(item.actor || 'Automation')} · ${esc(item.action || 'changed')}${field}<br><small>${esc(time(item.changedAt))}</small></li>`;
    }).join('')}</ul>`
  : '<h3>Vacancy changes by automation (0)</h3><p>None.</p>';

const classificationsHtml = classifications.length
  ? `<h3>Email classification and vacancy resolution (${n(classifications.length)})</h3><ol>${classifications.map((item) => {
      const title = [item.classification, item.company, item.jobTitle].filter(Boolean).join(' · ') || item.subject;
      const confidence = item.confidence === null || item.confidence === undefined ? '' : ` · ${Math.round(Number(item.confidence) * 100)}%`;
      const changed = Array.isArray(item.changedFields) && item.changedFields.length
        ? `<br><small>Classifier fields: ${item.changedFields.map((change) => `${esc(change.field)}=${esc(change.value)}`).join(' · ')}</small>`
        : '';
      const summary = item.summary ? `<br>${esc(item.summary)}` : '';
      return `<li><b>${esc(title)}</b><br><small>${esc(item.source || 'unknown source')}${confidence}</small>${summary}${changed}<br><small>${resolutionText(item)}</small><br><small>Subject: ${esc(item.subject || '')} · ${esc(time(item.classifiedAt))}</small></li>`;
    }).join('')}</ol>`
  : '<h3>Email classification and vacancy resolution</h3><p>None.</p>';

const subject = `GimmeJob · ${s.date} · ${n(t.jobRelevant)} job-relevant emails`;
const html = `
<h2>GimmeJob email automation — ${esc(s.date)}</h2>
<p><b>${n(t.received)}</b> emails received · <b>${n(t.processed)}</b> processed · <b>${n(t.pending)}</b> pending</p>
<h3>Job-relevant emails: ${n(t.jobRelevant)}</h3>
<table cellpadding="5" cellspacing="0" border="0">${classRows}</table>
<h3>Other email</h3>
<table cellpadding="5" cellspacing="0" border="0">
<tr><td>Job alerts</td><td style="text-align:right"><b>${n(t.jobAlerts)}</b></td></tr>
<tr><td>Service messages</td><td style="text-align:right"><b>${n(t.serviceMessages)}</b></td></tr>
<tr><td>Non-job</td><td style="text-align:right"><b>${n(t.nonJob)}</b></td></tr>
</table>
<h3>Automation</h3>
<table cellpadding="5" cellspacing="0" border="0">
<tr><td>Rule-based</td><td style="text-align:right"><b>${n(r.rule)}</b></td></tr>
<tr><td>OpenAI classified</td><td style="text-align:right"><b>${n(r.ai)}</b></td></tr>
<tr><td>AI avoided</td><td style="text-align:right"><b>${pct}%</b></td></tr>
<tr><td>OpenAI tokens</td><td style="text-align:right"><b>${n(ai.totalTokens)}</b></td></tr>
<tr><td>Needs review</td><td style="text-align:right"><b>${n(t.needsReview)}</b></td></tr>
<tr><td>Needs vacancy linking</td><td style="text-align:right"><b>${n(needsLinking)}</b></td></tr>
<tr><td>Reconciled in this run</td><td style="text-align:right"><b>${n(reconciliation.processed)}</b></td></tr>
<tr><td>Held</td><td style="text-align:right"><b>${n(t.held)}</b></td></tr>
<tr><td>Failed</td><td style="text-align:right"><b>${n(t.failed)}</b></td></tr>
</table>
${vacancyChangesHtml}
${classificationsHtml}
${importantHtml}
<p><small>Report window: ${esc(s.window?.startUtc)} → ${esc(s.window?.endUtc)} · Europe/Kyiv</small></p>`;

return [{ json: { reportDate: s.date, subject, html, totals: t, routing: r, ai, vacancyChangeCount: vacancyChanges.length, classificationChangeCount: classifications.length, needsLinking, reconciledCount: Number(reconciliation.processed ?? 0), importantCount: important.length } }];
